{
  "narratives": [
    {
      "item_code": "S5_MEDIA",
      "title_raw": "가. 적절한 (및 부적절한) 소화제 :",
      "start": "p3:L1",
      "end": "p3:L3"
    },
    {
      "item_code": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "start": "p3:L4",
      "end": "p3:L13"
    },
    {
      "item_code": "S5_FIREFIGHT",
      "title_raw": "다. 화재 진압 시 착용할 보호구 및 예방 조치 :",
      "start": "p3:L14",
      "end": "p3:L24"
    }
  ]
,
  "extras": [
    {
      "after_item": "S5_MEDIA",
      "title_raw": "가. 적절한 (및 부적절한) 소화제 :",
      "reason": "코드없음",
      "statements": [
        {
          "key": "내용",
          "value": "이물질과 관련된 소화시 알코올 포말, 이산화탄소 또는 물분무를 사용할 것."
        ,
          "line": "p3:L2"
        },
        {
          "key": "내용",
          "value": "질식소화시 건조한 모래 또는 흙을 사용할 것"
        ,
          "line": "p3:L3"
        }
      ]
    ,
      "suggested_code": "S5_MEDIA"
    ,
      "line": "p3:L1"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "reason": "코드없음",
      "statements": [
        {
          "key": "내용",
          "value": "가열시 용기가 폭발할 수 있음."
        ,
          "line": "p3:L5"
        },
        {
          "key": "내용",
          "value": "비인화성, 물질 자체는 타지 않으나 가열시 분해하여 부식성/독성 흄을 발생 할 수 있음"
        ,
          "line": "p3:L6"
        },
        {
          "key": "내용",
          "value": "열, 스파크, 화염에 의해 점화 할 수 있음"
        ,
          "line": "p3:L7"
        },
        {
          "key": "내용",
          "value": "일부는 탈 수 있으나 쉽게 점화하지 않음"
        ,
          "line": "p3:L8"
        },
        {
          "key": "내용",
          "value": "화재시 자극성, 독성 가스를 발생 할 수 있음"
        ,
          "line": "p3:L9"
        },
        {
          "key": "내용",
          "value": "물질의 흡입은 유해 할 수 있음"
        ,
          "line": "p3:L10"
        },
        {
          "key": "내용",
          "value": "일부 액체는 현기증, 질식을 유발하는 증기를 발생 할 수 있음"
        ,
          "line": "p3:L11"
        },
        {
          "key": "내용",
          "value": "일부는 화재나 가열시 폭발적으로 분해할 수 있음"
        ,
          "line": "p3:L12"
        },
        {
          "key": "내용",
          "value": "타는 동안 열분해 또는 연소에 의해 자극적이고 매우 유독한 가스가 발생될 수 있음"
        ,
          "line": "p3:L13"
        }
      ]
    ,
      "suggested_code": "S5_SPECIFIC"
    ,
      "line": "p3:L4"
    },
    {
      "after_item": "S5_FIREFIGHT",
      "title_raw": "다. 화재 진압 시 착용할 보호구 및 예방 조치 :",
      "reason": "코드없음",
      "statements": [
        {
          "key": "내용",
          "value": "구조자는 적절한 보호구를 착용하시오"
        ,
          "line": "p3:L15"
        },
        {
          "key": "내용",
          "value": "소화수의 처분을 위해 도랑을 파서 가두고 물질이 흩어지지 않게 하시오"
        ,
          "line": "p3:L16"
        },
        {
          "key": "내용",
          "value": "용융되어 운송될 수도 있음"
        ,
          "line": "p3:L17"
        },
        {
          "key": "내용",
          "value": "위험하지 않다면 화재지역에서 용기를 옮기시오"
        ,
          "line": "p3:L18"
        },
        {
          "key": "내용",
          "value": "지역을 벗어나 안전거리를 유지하여 소화하시오"
        ,
          "line": "p3:L19"
        },
        {
          "key": "내용",
          "value": "탱크 화재시 대규모 화재의 경우 무인 소화장비를 이용하고 불가능하다면 물러나 타게 놔두시오"
        ,
          "line": "p3:L20"
        },
        {
          "key": "내용",
          "value": "탱크 화재시 소화가 진화된 후에도 다량의 물로 용기를 식히시오"
        ,
          "line": "p3:L21"
        },
        {
          "key": "내용",
          "value": "탱크 화재시 압력 방출장치에서 고음이 있거나 탱크가 변색할 경우 즉시 물러나시오"
        ,
          "line": "p3:L22"
        },
        {
          "key": "내용",
          "value": "탱크 화재시 최대거리에서 소화하거나 무인 소화장비를 이용하시오"
        ,
          "line": "p3:L23"
        },
        {
          "key": "내용",
          "value": "탱크 화재시 화염에 휩싸인 탱크에서 물러나시오"
        ,
          "line": "p3:L24"
        }
      ]
    ,
      "suggested_code": "S5_FIREFIGHT"
    ,
      "line": "p3:L14"
    }
  ]
}

